public class JArrayRotateLeft {
	//Paso 1: Definir el metodo para rotar el arreglo a la izquierda en 1 posicion
	public static int[] rotateLeft(int[] lst) {
		//Paso 1.1: Almacenar el valor al frente en una variable local
		int first = lst[0];
		//Paso 1.2: Rotar los valores restantes del arreglo a la izquierda  
		for (int i = 0; i < lst.length - 1; i++) {
			lst[i] = lst[i + 1];
		}
		//Paso 1.3: Mover el valor del frente al final del arreglo
		lst[lst.length - 1] = first;
		//Paso 1.4: Devolver el arreglo rotado
		return lst;
	}
	//Paso 2: Definir el metodo para imprimir el arreglo
	public static void print(int[] array) {
		for (int x : array) {
			System.out.print(x + " ");
		}
		System.out.println();
	}
	public static void main(String[] args) {
		int[] values = {3, 8, 9, 8, 7, 5};
		System.out.println("Arreglo original:");
		print(values);
		System.out.println("Arreglo rotado:"); 
		print(rotateLeft(values));
	}
}

